update public.equipment_catalog_items c
set is_active=false,
    availability_status='unavailable',
    tour_scope='ATP'
where c.item_type='apparel'
  and c.brand in ('BlokUV','Qiaoden','IBKool','Artenga','Task','Penalti','Sofibela','Rainya','Original Pengwin','Ellesy','Rohnish')
  and not exists (
    select 1 from mapped m where m.sku=c.sku
  );
